// source/pages/Games.ts
function renderGames() {
  setGameBackground(null);
  const wrap = document.createElement("div");
  const title = document.createElement("center");
  const h1 = document.createElement("h1");
  h1.textContent = "GAMES";
  const h3 = document.createElement("h3");
  h3.textContent = "Educational games vibe-coded using paid Grok API.";
  title.append(h1, h3);
  wrap.appendChild(title);
  const list = document.createElement("div");
  list.id = "games-list";
  for (const game5 of listGames()) {
    const link = document.createElement("a");
    link.href = `#/game/${game5.slug}`;
    const body = document.createElement("div");
    const heading = document.createElement("h4");
    heading.textContent = game5.title;
    const img = document.createElement("img");
    img.src = game5.photo;
    img.alt = game5.title;
    img.loading = "lazy";
    const blurb = document.createElement("p");
    blurb.textContent = game5.description;
    body.append(heading, img, blurb);
    link.appendChild(Panel(body));
    list.appendChild(link);
  }
  wrap.appendChild(list);
  setOutlet(wrap);
}
function renderGame(slug) {
  const game5 = slug ? loadGame(slug) : null;
  if (!game5) {
    setGameBackground(null);
    const missing = document.createElement("div");
    missing.style.cssText = "min-height:70vh;display:flex;align-items:center;justify-content:center;color:#fff;font-size:1.5rem;";
    missing.textContent = `Game not found: ${slug ?? ""}`;
    setOutlet(missing);
    return () => {
      setGameBackground(null);
    };
  }
  setGameBackground(game5.initialiseBackground ?? null);
  const host = document.createElement("div");
  host.id = "game-root";
  setOutlet(host);
  const stop = game5.mount(host);
  return () => {
    stop();
    setGameBackground(null);
  };
}

